INSERT INTO qa_session (session_id, started_at, user_hash, channel, turn_cnt) VALUES ('s-20261128-c', '2026-11-28T08:51:19+08:00', NULL, NULL, 2) ON DUPLICATE KEY UPDATE turn_cnt=VALUES(turn_cnt);
INSERT INTO qa_turn (qa_id, session_id, turn_no, asked_at, question, answer, sql_text, sql_hash, intent, tables_json, feedback, feedback_note, model, latency_ms, ingested_at) VALUES ('Q20261127-0001', 's-20261127-a', 1, '2026-11-27T09:12:04+08:00', '近30天各渠道GMV是多少', '按 pay_time 归日、不含运费、退款不回冲，近 30 天（不含当天）各渠道 GMV 如下 SQL。', 'SELECT c.channel_name, SUM(p.pay_amt) AS gmv FROM dwd_pay_flow_di p LEFT JOIN dim_channel_df c ON p.channel_code = c.channel_code WHERE p.dt >= ''${dt-30}'' AND p.dt <= ''${dt-1}'' AND p.is_pay = 1 GROUP BY c.channel_name', '5a0b7c1d2e3f4a5b6c7d8e9f0a1b2c3d4e5f60718293a4b5c6d7e8f90a1b2c3d', '取数', '["dwd_pay_flow_di", "dim_channel_df"]', 1, NULL, 'deepseek', 8200, '2026-11-28T10:48:11+08:00') ON DUPLICATE KEY UPDATE qa_id=VALUES(qa_id);
INSERT INTO qa_turn (qa_id, session_id, turn_no, asked_at, question, answer, sql_text, sql_hash, intent, tables_json, feedback, feedback_note, model, latency_ms, ingested_at) VALUES ('Q20261127-0002', 's-20261127-a', 2, '2026-11-27T09:14:10+08:00', '人均客单价怎么算', '客单价 = GMV / 订单数。注意不要用 AVG(日客单价)，日客单价先平均会把小单量渠道的权重放大。', NULL, NULL, '口径确认', NULL, 0, NULL, 'deepseek', 6100, '2026-11-28T10:48:11+08:00') ON DUPLICATE KEY UPDATE qa_id=VALUES(qa_id);
INSERT INTO qa_turn (qa_id, session_id, turn_no, asked_at, question, answer, sql_text, sql_hash, intent, tables_json, feedback, feedback_note, model, latency_ms, ingested_at) VALUES ('Q20261127-0003', 's-20261127-a', 3, '2026-11-27T09:16:32+08:00', '不对啊 客单价不是应该用支付金额除以支付人数吗', '两个口径都存在：客单价（AOV）= GMV/订单数，用于商品策略；人均消费额 = GMV/支付人数，用于用户价值。你要哪一个决定分母。', NULL, NULL, '口径确认', NULL, 1, NULL, 'deepseek', 5400, '2026-11-28T10:48:11+08:00') ON DUPLICATE KEY UPDATE qa_id=VALUES(qa_id);
INSERT INTO qa_turn (qa_id, session_id, turn_no, asked_at, question, answer, sql_text, sql_hash, intent, tables_json, feedback, feedback_note, model, latency_ms, ingested_at) VALUES ('Q20261127-0004', 's-20261127-b', 1, '2026-11-27T10:03:55+08:00', '动销率是什么', '先确认口径：动销率一般指有销量的 SKU 数 / 在架 SKU 数，但「在架」按当前还是按统计周期平均，各公司口径不同。', NULL, NULL, '口径确认', NULL, 0, NULL, 'deepseek', 4800, '2026-11-28T10:48:11+08:00') ON DUPLICATE KEY UPDATE qa_id=VALUES(qa_id);
INSERT INTO qa_turn (qa_id, session_id, turn_no, asked_at, question, answer, sql_text, sql_hash, intent, tables_json, feedback, feedback_note, model, latency_ms, ingested_at) VALUES ('Q20261127-0005', 's-20261127-b', 2, '2026-11-27T10:06:41+08:00', '近30天各渠道GMV是多少', '同上一会话的写法，渠道维表左关联，注意渠道编码缺失的行会被归到 NULL 渠道。', 'SELECT c.channel_name, SUM(p.pay_amt) AS gmv FROM dwd_pay_flow_di p LEFT JOIN dim_channel_df c ON p.channel_code = c.channel_code WHERE p.dt >= ''${dt-30}'' AND p.dt <= ''${dt-1}'' AND p.is_pay = 1 GROUP BY c.channel_name', '5a0b7c1d2e3f4a5b6c7d8e9f0a1b2c3d4e5f60718293a4b5c6d7e8f90a1b2c3d', '取数', '["dwd_pay_flow_di", "dim_channel_df"]', 1, NULL, 'deepseek', 7300, '2026-11-28T10:48:12+08:00') ON DUPLICATE KEY UPDATE qa_id=VALUES(qa_id);
INSERT INTO qa_turn (qa_id, session_id, turn_no, asked_at, question, answer, sql_text, sql_hash, intent, tables_json, feedback, feedback_note, model, latency_ms, ingested_at) VALUES ('Q20261128-0001', 's-20261128-c', 1, '2026-11-28T08:51:19+08:00', '近30天各渠道GMV是多少', '同上，另建议同时输出订单数与客单价，避免只看 GMV 判断渠道好坏。', 'SELECT c.channel_name, SUM(p.pay_amt) AS gmv, COUNT(DISTINCT p.order_id) AS order_cnt FROM dwd_pay_flow_di p LEFT JOIN dim_channel_df c ON p.channel_code = c.channel_code WHERE p.dt >= ''${dt-30}'' AND p.dt <= ''${dt-1}'' AND p.is_pay = 1 GROUP BY c.channel_name', 'c9d8e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3b2c1d0e9f8a7b6c5d4e3f2a1b0c9d8', '取数', '["dwd_pay_flow_di", "dim_channel_df"]', 1, NULL, 'deepseek', 7900, '2026-11-28T10:48:12+08:00') ON DUPLICATE KEY UPDATE qa_id=VALUES(qa_id);
INSERT INTO qa_turn (qa_id, session_id, turn_no, asked_at, question, answer, sql_text, sql_hash, intent, tables_json, feedback, feedback_note, model, latency_ms, ingested_at) VALUES ('Q20261128-0002', 's-20261128-c', 2, '2026-11-28T08:53:02+08:00', '复购用户怎么圈', '复购 = 历史上支付过两次以上。按订单维度 COUNT(DISTINCT order_id) >= 2，不是按支付流水条数（一次支付可能拆多笔）。', NULL, NULL, '分析', NULL, 1, NULL, 'deepseek', 6600, '2026-11-28T10:48:12+08:00') ON DUPLICATE KEY UPDATE qa_id=VALUES(qa_id);
